/* Live Earth Orbit: the procedural shader Earth, clouds, atmosphere, stars,
 * the Sun, satellite point sprites, pad markers and a small ISS model.
 *
 * Textures (site/assets/img/earth/) are generated by
 * scripts/build_earth_textures.py from the Natural Earth land mask. Biomes,
 * relief, clouds and city lights are STYLISED impressions, not maps.
 *
 * Scene frame: Earth-Centred Inertial (ECI) mapped to three.js as
 * (x, y, z)_three = (x, z, −y)_ECI / 6378.137 km, so +Y is the north pole.
 * The Earth-fixed group is rotated about +Y by Greenwich Mean Sidereal Time.
 */
import * as THREE from "three";

export const eciToWorld = (p, out) => out.set(p.x, p.z, -p.y);

/* latitude/longitude (deg) → unit vector in the Earth-fixed group */
export function llToLocal(lat, lon, r = 1, out = new THREE.Vector3()) {
  const la = lat * Math.PI / 180, lo = lon * Math.PI / 180;
  return out.set(r * Math.cos(la) * Math.cos(lo), r * Math.sin(la), -r * Math.cos(la) * Math.sin(lo));
}

const CLOUD_GLSL = /* glsl */`
uniform sampler2D uClouds;
uniform float uCloudPhase;
uniform float uDetail;           // 0 far away … 1 close up: adds sub-texel noise detail
// value noise, hash after Inigo Quilez (MIT)
float hash3(vec3 p) { p = fract(p * 0.3183099 + 0.1); p *= 17.0; return fract(p.x * p.y * p.z * (p.x + p.y + p.z)); }
float vnoise(vec3 x) {
  vec3 i = floor(x), f = fract(x); f = f * f * (3.0 - 2.0 * f);
  return mix(mix(mix(hash3(i), hash3(i + vec3(1, 0, 0)), f.x), mix(hash3(i + vec3(0, 1, 0)), hash3(i + vec3(1, 1, 0)), f.x), f.y),
             mix(mix(hash3(i + vec3(0, 0, 1)), hash3(i + vec3(1, 0, 1)), f.x), mix(hash3(i + vec3(0, 1, 1)), hash3(i + vec3(1, 1, 1)), f.x), f.y), f.z);
}
float detailN(vec3 p) { return vnoise(p * 180.0) * 0.62 + vnoise(p * 520.0) * 0.38; }
// Zonal winds (stylised): easterly trades in the tropics, westerlies at mid-latitudes.
float windU(float latDeg) {
  float a = abs(latDeg);
  return mix(-0.7, 1.0, smoothstep(22.0, 36.0, a)) * (1.0 - 0.6 * smoothstep(62.0, 82.0, a));
}
// Two phase-shifted samples cross-faded ("flow map" trick) so drift never shears forever.
float cloudAt(vec2 uv) {
  float w = windU((uv.y - 0.5) * 180.0) * 0.03;
  float p1 = fract(uCloudPhase), p2 = fract(uCloudPhase + 0.5);
  float c1 = texture2D(uClouds, uv - vec2(w * p1, 0.0)).r;
  float c2 = texture2D(uClouds, uv - vec2(w * p2 - 0.41, 0.0)).r;
  float k = abs(2.0 * p1 - 1.0);
  float c = mix(c1, c2, smoothstep(0.0, 1.0, k));
  return smoothstep(0.04, 0.92, c);
}`;

export function makeEarth(tex) {
  const group = new THREE.Group();                 // Earth-fixed frame
  const common = {
    uSunDir: { value: new THREE.Vector3(1, 0, 0) },
    uClouds: { value: tex.clouds },
    uCloudPhase: { value: 0 },
    uDetail: { value: 0 }
  };

  const earthMat = new THREE.ShaderMaterial({
    uniforms: Object.assign({
      uAlbedo: { value: tex.albedo }, uData: { value: tex.data }, uNormal: { value: tex.normal },
      uLights: { value: 1 }
    }, common),
    vertexShader: /* glsl */`
      varying vec2 vUv; varying vec3 vN; varying vec3 vP; varying vec3 vL;
      void main() {
        vUv = uv; vL = position;
        vN = normalize(mat3(modelMatrix) * normal);
        vec4 wp = modelMatrix * vec4(position, 1.0);
        vP = wp.xyz;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }`,
    fragmentShader: /* glsl */`
      uniform sampler2D uAlbedo, uData, uNormal;
      uniform vec3 uSunDir;
      uniform float uLights;
      varying vec2 vUv; varying vec3 vN; varying vec3 vP; varying vec3 vL;
      ${CLOUD_GLSL}
      void main() {
        vec3 n0 = normalize(vN);
        vec3 V = normalize(cameraPosition - vP);
        vec3 L = uSunDir;
        vec3 alb = texture2D(uAlbedo, vUv).rgb;
        vec4 dat = texture2D(uData, vUv);
        vec3 nm = texture2D(uNormal, vUv).rgb;
        float land = dat.r, lights = dat.g, ice = nm.b;
        if (uDetail > 0.0) alb *= 1.0 + (detailN(vL * 1.7) - 0.5) * 0.45 * uDetail * (0.35 + 0.65 * land);
        // local east / north on the sphere (pole = world +Y)
        vec3 east = cross(vec3(0.0, 1.0, 0.0), n0);
        float el = length(east);
        east = el > 1e-4 ? east / el : vec3(1.0, 0.0, 0.0);
        vec3 north = cross(n0, east);
        vec3 n = normalize(n0 - 0.9 * ((nm.r - 0.5) * east + (nm.g - 0.5) * north));
        float ndl0 = dot(n0, L);
        float ndl = dot(n, L);
        float day = smoothstep(-0.08, 0.22, ndl0);
        float term = exp(-pow(ndl0 / 0.14, 2.0));
        float cl = cloudAt(vUv);
        // cloud shadow: look up the cloud a little towards the Sun
        float cosLat = max(sqrt(1.0 - n0.y * n0.y), 0.15);
        vec2 sh = vec2(dot(L, east) / cosLat / 6.2831853, dot(L, north) / 3.1415927) * 0.004;
        float cls = cloudAt(vUv + sh);
        float water = (1.0 - land) * (1.0 - ice);

        // surface: wrapped diffuse (a hint of forward-scattered skylight at dusk)
        float diff = max(ndl, 0.0) * smoothstep(-0.06, 0.12, ndl0);   // relief never lights the night side
        diff = mix(diff, smoothstep(-0.1, 1.0, ndl0), 0.15);
        vec3 col = alb * alb * (diff * 1.55 + 0.004);       // alb² ≈ sRGB→linear, cheap
        col *= 1.0 - 0.6 * cls * day;
        col = mix(col, col * vec3(1.15, 0.78, 0.55), term * 0.55);

        // ocean: sun glint (Blinn-Phong lobes) and sky reflection (Fresnel)
        vec3 H = normalize(L + V);
        float nh = max(dot(n0, H), 0.0);
        float spec = pow(nh, 1400.0) * 0.8 + pow(nh, 180.0) * 0.035 + pow(nh, 18.0) * 0.01;
        float ndv = max(dot(n0, V), 0.0);
        float fres = 0.02 + 0.98 * pow(1.0 - ndv, 5.0);
        vec3 glintCol = mix(vec3(1.0, 0.62, 0.35), vec3(1.0, 0.95, 0.85), smoothstep(0.0, 0.35, ndl0));
        col += water * spec * glintCol * smoothstep(-0.02, 0.12, ndl0) * (1.0 - cl);
        col += water * fres * vec3(0.14, 0.3, 0.62) * day * 0.55;

        // aerial perspective: haze thickens towards the limb
        float rim = pow(1.0 - ndv, 3.0);
        vec3 sky = mix(vec3(0.22, 0.5, 1.0), vec3(1.0, 0.48, 0.22), term * 0.75);
        col = mix(col, sky * day * 0.8, rim * 0.5);
        col += vec3(0.02, 0.05, 0.12) * day * 0.5;

        // night side: stylised city lights, dimmed by cloud
        float night = 1.0 - smoothstep(-0.2, 0.04, ndl0);
        float li = lights * lights;
        vec3 city = vec3(1.0, 0.62, 0.28) * pow(lights, 1.6) * 2.8 + vec3(1.0, 0.9, 0.7) * pow(lights, 5.0) * 2.4;
        col += city * night * (1.0 - 0.75 * cl) * uLights;
        // faint moonless-night ocean/land so the dark side is not pure black
        col += alb * alb * 0.006 * night;

        gl_FragColor = vec4(col, 1.0);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }`
  });
  const earth = new THREE.Mesh(new THREE.SphereGeometry(1, 192, 128), earthMat);
  group.add(earth);

  const cloudMat = new THREE.ShaderMaterial({
    uniforms: common,
    transparent: true, depthWrite: false,
    vertexShader: /* glsl */`
      varying vec2 vUv; varying vec3 vN; varying vec3 vP; varying vec3 vL;
      void main() {
        vUv = uv; vN = normalize(mat3(modelMatrix) * normal); vL = position;
        vec4 wp = modelMatrix * vec4(position, 1.0); vP = wp.xyz;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }`,
    fragmentShader: /* glsl */`
      uniform vec3 uSunDir;
      varying vec2 vUv; varying vec3 vN; varying vec3 vP; varying vec3 vL;
      ${CLOUD_GLSL}
      void main() {
        float c = cloudAt(vUv);
        if (uDetail > 0.0) {
          float dn = detailN(vL);
          c = clamp(c + (dn - 0.5) * 0.9 * uDetail * smoothstep(0.0, 0.35, c) * smoothstep(1.0, 0.6, c), 0.0, 1.0);
          c = mix(c, smoothstep(0.15, 0.85, c), uDetail);
        }
        vec3 n = normalize(vN);
        float ndl = dot(n, uSunDir);
        float day = smoothstep(-0.14, 0.2, ndl);
        vec3 tint = mix(vec3(1.0, 0.5, 0.26), vec3(1.0, 0.99, 0.97), smoothstep(-0.02, 0.3, ndl));
        vec3 col = tint * (0.1 + 1.05 * max(ndl, 0.0)) * day + vec3(0.006, 0.009, 0.016);
        vec3 V = normalize(cameraPosition - vP);
        float limb = pow(1.0 - max(dot(n, V), 0.0), 3.0);
        gl_FragColor = vec4(col, c * (0.94 - 0.4 * limb) * mix(0.3, 1.0, day));
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }`
  });
  const clouds = new THREE.Mesh(new THREE.SphereGeometry(1.0065, 144, 96), cloudMat);
  clouds.renderOrder = 1;
  group.add(clouds);

  // Atmosphere: analytic glow from the closest approach of each view ray to
  // Earth's centre (exponential density, scale height exaggerated ~10×).
  const atmoMat = new THREE.ShaderMaterial({
    uniforms: { uSunDir: common.uSunDir },
    transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
    vertexShader: /* glsl */`
      varying vec3 vP;
      void main() { vec4 wp = modelMatrix * vec4(position, 1.0); vP = wp.xyz; gl_Position = projectionMatrix * viewMatrix * wp; }`,
    fragmentShader: /* glsl */`
      uniform vec3 uSunDir;
      varying vec3 vP;
      void main() {
        vec3 ro = cameraPosition, rd = normalize(vP - ro);
        float t = max(-dot(ro, rd), 0.0);
        vec3 pc = ro + rd * t;
        float h = length(pc);
        float alt = h - 1.0;
        float g = alt > 0.0 ? exp(-alt / 0.0135) : exp(alt / 0.04);
        vec3 up = pc / max(h, 1e-4);
        float mu = dot(up, uSunDir);
        float lit = smoothstep(-0.3, 0.16, mu);
        float sunset = exp(-pow((mu - 0.02) / 0.17, 2.0));
        vec3 col = mix(vec3(0.24, 0.52, 1.0), vec3(1.0, 0.46, 0.2), sunset * 0.85);
        float phase = 1.0 + 1.3 * pow(max(dot(rd, uSunDir), 0.0), 8.0);
        col *= lit * phase * g * 1.05;
        gl_FragColor = vec4(col, 1.0);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }`
  });
  const atmo = new THREE.Mesh(new THREE.SphereGeometry(1.085, 128, 96), atmoMat);
  atmo.renderOrder = 2;

  return {
    group, earth, clouds, atmo, uniforms: common, earthMat,
    update(camDist) {
      common.uDetail.value = Math.min(1, Math.max(0, (1.9 - camDist) / 0.6));
      atmoMat.side = camDist < 1.085 ? THREE.BackSide : THREE.FrontSide;
    }
  };
}

/* ------------------------------------------------------------------ stars (real, from the HYG/d3-celestial catalogue) */
export function makeStars(data) {
  const rows = (data && data.stars) || [];
  const N = rows.length;
  const pos = new Float32Array(N * 3), col = new Float32Array(N * 3), size = new Float32Array(N);
  const c = new THREE.Color();
  for (let i = 0; i < N; i++) {
    const [, ra, dec, mag, bv] = rows[i];
    const a = ra * Math.PI / 180, d = dec * Math.PI / 180, R = 600;
    // equatorial J2000 unit vector (≈ ECI), mapped to the scene frame
    pos[i * 3] = R * Math.cos(d) * Math.cos(a);
    pos[i * 3 + 1] = R * Math.sin(d);
    pos[i * 3 + 2] = -R * Math.cos(d) * Math.sin(a);
    const t = Math.max(-0.4, Math.min(2.0, bv == null ? 0.6 : bv));        // B−V colour index → tint
    c.setRGB(t < 0.4 ? 0.75 + 0.25 * (t + 0.4) / 0.8 : 1, t < 0.4 ? 0.85 + 0.15 * (t + 0.4) / 0.8 : 1 - 0.25 * (t - 0.4) / 1.6, t < 0.4 ? 1 : 1 - 0.55 * (t - 0.4) / 1.6);
    const b = Math.pow(10, -0.4 * (mag - 1.0));                               // flux relative to mag 1
    col[i * 3] = c.r; col[i * 3 + 1] = c.g; col[i * 3 + 2] = c.b;
    size[i] = Math.min(1, b);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
  g.setAttribute("aColor", new THREE.BufferAttribute(col, 3));
  g.setAttribute("aB", new THREE.BufferAttribute(size, 1));
  const m = new THREE.ShaderMaterial({
    uniforms: { uPx: { value: 1 } },
    transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
    vertexShader: /* glsl */`
      attribute vec3 aColor; attribute float aB; uniform float uPx;
      varying vec3 vC; varying float vB;
      void main() {
        vC = aColor; vB = aB;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        gl_PointSize = uPx * (1.4 + 4.2 * sqrt(aB));
      }`,
    fragmentShader: /* glsl */`
      varying vec3 vC; varying float vB;
      void main() {
        vec2 p = gl_PointCoord * 2.0 - 1.0; float r = dot(p, p);
        if (r > 1.0) discard;
        float a = exp(-r * 5.0) * (0.25 + 0.95 * sqrt(vB)) + smoothstep(0.2, 0.0, r) * 0.25;
        gl_FragColor = vec4(vC * a, 1.0);
      }`
  });
  const pts = new THREE.Points(g, m);
  pts.renderOrder = -1;
  pts.frustumCulled = false;
  return pts;
}

/* ------------------------------------------------------------------ the Sun (glow sprite far away) */
export function makeSun() {
  const cv = document.createElement("canvas"); cv.width = cv.height = 256;
  const x = cv.getContext("2d");
  const gr = x.createRadialGradient(128, 128, 0, 128, 128, 128);
  gr.addColorStop(0, "rgba(255,255,255,1)"); gr.addColorStop(0.06, "rgba(255,250,235,1)");
  gr.addColorStop(0.12, "rgba(255,220,160,.55)"); gr.addColorStop(0.35, "rgba(255,170,90,.12)"); gr.addColorStop(1, "rgba(255,140,60,0)");
  x.fillStyle = gr; x.fillRect(0, 0, 256, 256);
  const t = new THREE.CanvasTexture(cv); t.colorSpace = THREE.SRGBColorSpace;
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: t, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true, toneMapped: false }));
  s.scale.setScalar(90);
  s.renderOrder = -1;
  return s;
}

/* ------------------------------------------------------------------ satellites as instanced glowing points */
export function makeSatPoints(maxN) {
  const g = new THREE.BufferGeometry();
  const pos = new Float32Array(maxN * 3), col = new Float32Array(maxN * 3), size = new Float32Array(maxN), state = new Float32Array(maxN);
  g.setAttribute("position", new THREE.BufferAttribute(pos, 3).setUsage(THREE.DynamicDrawUsage));
  g.setAttribute("aColor", new THREE.BufferAttribute(col, 3));
  g.setAttribute("aSize", new THREE.BufferAttribute(size, 1));
  g.setAttribute("aState", new THREE.BufferAttribute(state, 1).setUsage(THREE.DynamicDrawUsage));
  g.setDrawRange(0, 0);
  const m = new THREE.ShaderMaterial({
    uniforms: { uPx: { value: 1 }, uSunDir: { value: new THREE.Vector3(1, 0, 0) }, uTime: { value: 0 } },
    transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
    vertexShader: /* glsl */`
      attribute vec3 aColor; attribute float aSize; attribute float aState;
      uniform float uPx; uniform vec3 uSunDir; uniform float uTime;
      varying vec3 vC; varying float vS; varying float vSz;
      void main() {
        vec4 mv = modelViewMatrix * vec4(position, 1.0);
        gl_Position = projectionMatrix * mv;
        if (aState < 0.5) { gl_PointSize = 0.0; gl_Position = vec4(2.0, 2.0, 2.0, 1.0); return; }
        float d = -mv.z;
        // cylindrical Earth-shadow test: satellites in eclipse dim to a faint dot
        float s = dot(position, uSunDir);
        float perp = length(position - s * uSunDir);
        float shade = (s < 0.0 && perp < 1.0) ? 0.3 : 1.0;
        float sz = aSize * uPx * clamp(3.4 / d, 0.55, 2.4);
        if (aState > 1.5) sz = max(sz * 2.0, 11.0 * uPx);
        if (aState > 2.5) sz = max(sz * 1.3, 15.0 * uPx) * (1.0 + 0.12 * sin(uTime * 4.0));
        gl_PointSize = max(sz, 2.0 * uPx);
        vSz = gl_PointSize / uPx;
        vC = aColor * (aState > 1.5 ? 1.4 : shade);
        vS = aState;
      }`,
    fragmentShader: /* glsl */`
      varying vec3 vC; varying float vS; varying float vSz;
      void main() {
        vec2 p = gl_PointCoord * 2.0 - 1.0; float r = length(p);
        if (r > 1.0) discard;
        // tiny points: a flat dot (a glow profile would fall between pixel centres)
        float small = 1.0 - smoothstep(2.5, 5.0, vSz);
        float core = smoothstep(0.55, 0.0, r);
        float halo = exp(-r * r * 5.0) * 0.6;
        vec3 c = vC * (halo + core * 1.2) + core * core * 0.3;
        c = mix(c, vC * 0.95, small);
        if (vS > 2.5) c += vC * smoothstep(0.1, 0.0, abs(r - 0.82)) * 1.3;
        gl_FragColor = vec4(c, 1.0);
      }`
  });
  const pts = new THREE.Points(g, m);
  pts.frustumCulled = false;
  pts.renderOrder = 4;
  return { points: pts, pos, col, size, state, geo: g, mat: m };
}

/* ------------------------------------------------------------------ pulsing ground markers (launch pads, observer) */
export function makeMarkers(maxN) {
  const g = new THREE.BufferGeometry();
  const pos = new Float32Array(maxN * 3), col = new Float32Array(maxN * 3), phase = new Float32Array(maxN), hot = new Float32Array(maxN);
  g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
  g.setAttribute("aColor", new THREE.BufferAttribute(col, 3));
  g.setAttribute("aPhase", new THREE.BufferAttribute(phase, 1));
  g.setAttribute("aHot", new THREE.BufferAttribute(hot, 1));
  g.setDrawRange(0, 0);
  const m = new THREE.ShaderMaterial({
    uniforms: { uPx: { value: 1 }, uTime: { value: 0 } },
    transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
    vertexShader: /* glsl */`
      attribute vec3 aColor; attribute float aPhase; attribute float aHot;
      uniform float uPx; uniform float uTime;
      varying vec3 vC; varying float vT; varying float vHot; varying float vFace;
      void main() {
        vec4 wp = modelMatrix * vec4(position, 1.0);
        vec4 mv = viewMatrix * wp;
        gl_Position = projectionMatrix * mv;
        vFace = dot(normalize(wp.xyz), normalize(cameraPosition - wp.xyz));
        vC = aColor; vHot = aHot;
        vT = fract(uTime * 0.45 + aPhase);
        gl_PointSize = uPx * (aHot > 0.5 ? 46.0 : 26.0);
      }`,
    fragmentShader: /* glsl */`
      varying vec3 vC; varying float vT; varying float vHot; varying float vFace;
      void main() {
        if (vFace < 0.02) discard;
        vec2 p = gl_PointCoord * 2.0 - 1.0; float r = length(p);
        if (r > 1.0) discard;
        float dot_ = smoothstep(0.2, 0.08, r);
        float ring = smoothstep(0.07, 0.0, abs(r - (0.18 + 0.8 * vT))) * (1.0 - vT);
        float halo = exp(-r * r * 14.0) * 0.6;
        vec3 c = vC * (dot_ * 1.3 + ring * (vHot > 0.5 ? 1.4 : 0.8) + halo);
        gl_FragColor = vec4(c * smoothstep(0.02, 0.2, vFace), 1.0);
      }`
  });
  const pts = new THREE.Points(g, m);
  pts.frustumCulled = false;
  pts.renderOrder = 5;
  return { points: pts, pos, col, phase, hot, geo: g, mat: m };
}

/* ------------------------------------------------------------------ a small ISS (procedural, not to scale) */
function arrayTexture() {
  const cv = document.createElement("canvas"); cv.width = 64; cv.height = 256;
  const x = cv.getContext("2d");
  x.fillStyle = "#3a2a14"; x.fillRect(0, 0, 64, 256);
  for (let j = 0; j < 32; j++) for (let i = 0; i < 4; i++) {
    const v = 150 + ((i * 7 + j * 13) % 5) * 12;
    x.fillStyle = `rgb(${v},${Math.round(v * 0.62)},${Math.round(v * 0.25)})`;
    x.fillRect(i * 16 + 1, j * 8 + 1, 14, 6);
  }
  const t = new THREE.CanvasTexture(cv); t.colorSpace = THREE.SRGBColorSpace;
  return t;
}
export function makeISS() {
  const root = new THREE.Group();
  const metal = new THREE.MeshStandardMaterial({ color: 0xd4d8e0, roughness: 0.45, metalness: 0.55 });
  const white = new THREE.MeshStandardMaterial({ color: 0xf2f4f8, roughness: 0.7, metalness: 0.1 });
  const arr = new THREE.MeshStandardMaterial({ map: arrayTexture(), roughness: 0.35, metalness: 0.4, side: THREE.DoubleSide, emissive: 0x2a1604, emissiveIntensity: 0.4 });
  // Integrated truss along local Z (perpendicular to the flight direction)
  const truss = new THREE.Mesh(new THREE.BoxGeometry(0.035, 0.03, 1.0), metal);
  root.add(truss);
  // Pressurised modules along local X (flight direction): Zvezda/Zarya aft, Destiny/Harmony forward
  const cyl = (r, l, x, z = 0, rotY = false) => {
    const c = new THREE.Mesh(new THREE.CylinderGeometry(r, r, l, 20), white);
    c.rotation.z = Math.PI / 2; if (rotY) { c.rotation.z = 0; c.rotation.x = Math.PI / 2; }
    c.position.set(x, -0.035, z); root.add(c); return c;
  };
  cyl(0.024, 0.34, -0.2); cyl(0.028, 0.28, 0.12); cyl(0.022, 0.1, 0.3);
  cyl(0.024, 0.13, 0.28, 0.09, true); cyl(0.024, 0.11, 0.28, -0.08, true);      // Kibo, Columbus
  // Zvezda's small arrays
  const small = new THREE.Mesh(new THREE.PlaneGeometry(0.05, 0.16), arr);
  small.position.set(-0.3, -0.035, 0.1); small.rotation.x = Math.PI / 2; root.add(small);
  const small2 = small.clone(); small2.position.z = -0.1; root.add(small2);
  // Radiators
  for (const z of [-0.14, 0.14]) {
    const r = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.003, 0.05), white);
    r.position.set(0, 0.0, z); r.rotation.x = 0.3; root.add(r);
  }
  // Four pairs of main solar array wings; each pair on a rotary joint about the truss (Z)
  const wings = [];
  for (const z of [-0.47, -0.3, 0.3, 0.47]) {
    const joint = new THREE.Group(); joint.position.z = z; root.add(joint);
    for (const s of [-1, 1]) {
      for (const dz of [-0.03, 0.03]) {
        const p = new THREE.Mesh(new THREE.PlaneGeometry(0.05, 0.34), arr);
        p.rotation.y = Math.PI / 2;                       // blanket normal ⟂ truss
        p.position.set(0, s * 0.19, dz); joint.add(p);
      }
    }
    wings.push(joint);
  }
  root.userData.wings = wings;
  return root;
}
